import{_ as i,p as e,q as r,Y as t}from"./framework-e1bed10d.js";const n={},l=t('<h1 id="字符串" tabindex="-1"><a class="header-anchor" href="#字符串" aria-hidden="true">#</a> 字符串</h1><h2 id="特点" tabindex="-1"><a class="header-anchor" href="#特点" aria-hidden="true">#</a> 特点</h2><ol><li>java中所有的双引号字面值都是String类的对象实现</li><li>字符串是不可变的，对字符串进行拼接、截取、替换、转换、替换、遍历等操作，都会产生新的字符串对象，不会改变原来的字符串对象</li><li>相同的字符串在内存中只有一份对象，相同字符串内容的不同变量<code>共享</code>同一个对象</li></ol><h2 id="创建string对象" tabindex="-1"><a class="header-anchor" href="#创建string对象" aria-hidden="true">#</a> 创建String对象</h2><ol><li>通过字面值创建String对象:String s = &quot;hello&quot;;</li><li>通过有参构造传入字符串创建:String s = new String(&quot;hello&quot;);</li><li>通过char数组创建String对象:String s = new String(char[] {&#39;h&#39;,&#39;e&#39;,&#39;l&#39;,&#39;l&#39;,&#39;o&#39;},int offset, int count);</li><li>通过字节数组创建String对象:String s = new String(byte[] {104,101,108,108,111},int offset, int length);</li><li>通过字符串生成器创建String对象:String s = new String(StringBuilder builder);</li><li>通过字符串缓冲器创建String对象:String s = new String(StringBuffer buffer);</li></ol><h2 id="常用方法" tabindex="-1"><a class="header-anchor" href="#常用方法" aria-hidden="true">#</a> 常用方法</h2><h3 id="静态方法" tabindex="-1"><a class="header-anchor" href="#静态方法" aria-hidden="true">#</a> 静态方法</h3><ol><li>static String format(String format, Object... args)：使用指定的格式字符串和参数返回格式化字符串</li><li>static String valueOf([boolean b|chart[] c|char c|byte b|short s|int i|long l|float f|double d])：返回参数的字符串表示形式</li><li>static String join(CharSequence delimiter, CharSequence... elements)：返回由CharSequence元素的副本与指定delimiter的副本连接在一起组成的新字符串</li></ol><h3 id="比较方法" tabindex="-1"><a class="header-anchor" href="#比较方法" aria-hidden="true">#</a> 比较方法</h3><ol><li>boolean equals(String s)：判断两个字符串是否相等</li><li>boolean equalsIgnoreCase(String s)：忽略大小写判断两个字符串是否相等</li><li>int compareTo(String s)：比较两个字符串的大小</li><li>int compareToIgnoreCase(String s)：忽略大小写比较两个字符串的大小</li></ol><h3 id="获取方法" tabindex="-1"><a class="header-anchor" href="#获取方法" aria-hidden="true">#</a> 获取方法</h3><ol><li>int length()：获取字符串的长度</li><li>char charAt(int index)：获取指定索引处的字符</li><li>int codePointAt(int index)：返回指定索引处的字符（Unicode 代码点）</li><li>int indexOf(String s)：获取指定字符串在字符串中的索引</li><li>int indexOf(String s, int fromIndex)：获取指定字符串在字符串中的索引，从指定索引开始</li><li>int lastIndexOf(String s)：获取指定字符串在字符串中的索引，从字符串末尾开始</li><li>int lastIndexOf(String s, int fromIndex)：获取指定字符串在字符串中的索引，从指定索引开始，从字符串末尾开始</li><li>String substring(int beginIndex)：获取指定索引开始到字符串末尾的子字符串</li><li>String substring(int beginIndex, int endIndex)：获取指定索引开始到指定索引结束的子字符串</li></ol><h3 id="修改方法" tabindex="-1"><a class="header-anchor" href="#修改方法" aria-hidden="true">#</a> 修改方法</h3><ol><li>String toLowerCase()：将字符串转换为小写</li><li>String toUpperCase()：将字符串转换为大写</li><li>String trim()：删除字符串两端所有的空格</li><li>String replace(char oldChar, char newChar)：替换字符串中指定的字符</li><li>String replace(CharSequence target, CharSequence replacement)：替换字符串中指定的字符序列</li><li>String replaceAll(String regex, String replacement)：替换字符串中指定的正则表达式</li><li>String replaceFirst(String regex, String replacement)：替换字符串中指定的正则表达式的第一个匹配项</li></ol><h3 id="转换方法" tabindex="-1"><a class="header-anchor" href="#转换方法" aria-hidden="true">#</a> 转换方法</h3><ol><li>String[] split(String regex)：分割字符串，返回一个字符串数组</li><li>Char[] toCharArray()：将字符串转换为字符数组</li><li>byte[] getBytes(Charset charset)：使用给定的 charset 将此 String 编码为字节序列，并将结果存储到新的字节数组中</li><li>byte[] getBytes()：使用平台的默认字符集将此 String 编码为字节序列，并将结果存储到新的字节数组中</li><li>void getChars(int srcBegin, int srcEnd, char[] dst, int dstBegin)：将此字符串中的字符复制到目标字符数组中</li></ol><h3 id="拼接字符串" tabindex="-1"><a class="header-anchor" href="#拼接字符串" aria-hidden="true">#</a> 拼接字符串</h3><ol><li>String concat(String str)：拼接字符串，返回一个新字符串</li></ol><h3 id="判断方法" tabindex="-1"><a class="header-anchor" href="#判断方法" aria-hidden="true">#</a> 判断方法</h3><ol><li>boolean startsWith(String prefix)：判断字符串是否以指定前缀开头</li><li>boolean endsWith(String suffix)：判断字符串是否以指定后缀结尾</li><li>boolean contains(CharSequence seq)：判断字符串是否包含指定字符序列</li><li>boolean isEmpty()：判断字符串是否为空</li><li>boolean isBlank()：如果字符串为空或仅包含 空白 代码点，则返回 true，否则返回 false</li></ol><h2 id="stringbuilder" tabindex="-1"><a class="header-anchor" href="#stringbuilder" aria-hidden="true">#</a> StringBuilder</h2><p>StringBuilder是一个可变字符串，主要用于字符串拼接，string使用+每拼接一次字符串，就会创建一个新的字符串对象，消耗内存</p><p>StringBuilder自带一个缓冲区，每次拼接都会将结果放到缓冲区，不会创建新的对象，拼接结束后，将缓冲区中的内容复制到新的字符串对象中，不会产生垃圾</p><p>用作StringBuffer在字符串缓冲区被单个线程使用的地方（通常情况下）的替代品，建议优先使用此类而不是StringBuffer，使用StringBuilder做字符串拼接， 线程是不安全的</p><h3 id="构造方法" tabindex="-1"><a class="header-anchor" href="#构造方法" aria-hidden="true">#</a> 构造方法</h3><ol><li>StringBuilder()：构造一个没有字符且初始容量为 16 个字符的字符串生成器。</li><li>StringBuilder(int capacity)：构造一个没有字符的字符串生成器，初始容量由 capacity 参数指定。</li><li>StringBuilder(CharSequence seq)：构造一个字符串生成器，其中包含与指定的 CharSequence 相同的字符。</li><li>StringBuilder(String str)：构造一个初始化为指定字符串内容的字符串生成器</li></ol><h3 id="追加方法" tabindex="-1"><a class="header-anchor" href="#追加方法" aria-hidden="true">#</a> 追加方法</h3><ol><li>StringBuilder append(boolean b)：将 boolean 参数的字符串表示形式附加到序列中。</li><li>StringBuilder append(char c)：将 char 参数的字符串表示形式附加到此序列。</li><li>StringBuilder append(char[] str)：将 char 数组参数的字符串表示形式附加到此序列。</li><li>StringBuilder append(char[] str, int offset, int len)：将 char 数组参数的子数组的字符串表示形式附加到此序列。</li><li>StringBuilder append(double d)：将 double 参数的字符串表示形式附加到此序列。</li><li>StringBuilder append(float f)：将 float 参数的字符串表示附加到此序列。</li><li>StringBuilder append(int i)：将 int 参数的字符串表示形式附加到此序列。</li><li>StringBuilder append(long lng)：将 long 参数的字符串表示形式附加到此序列。</li><li>StringBuilder append(CharSequence s)：将指定的字符序列附加到此 Appendable 。</li><li>StringBuilder append(CharSequence s, int start, int end)：将指定的 CharSequence 的子序列附加到此序列。</li><li>StringBuilder append(Object obj)：附加 Object 参数的字符串表示形式。</li><li>StringBuilder append(String str)：将指定的字符串附加到此字符序列。</li><li>StringBuilder append(StringBuffer sb)：将指定的 StringBuffer 附加到此序列</li></ol><h3 id="插入方法" tabindex="-1"><a class="header-anchor" href="#插入方法" aria-hidden="true">#</a> 插入方法</h3><ol><li>StringBuilder insert(int offset, boolean b)：将 boolean 参数的字符串表示形式插入此序列。</li><li>StringBuilder insert(int offset, char c) 将 char 参数的字符串表示形式插入此序列。</li><li>StringBuilder insert(int offset, char[] str)：将 char 数组参数的字符串表示形式插入到此序列中。</li><li>StringBuilder insert(int index, char[] str, int offset, int len)：将 str 数组参数的子数组的字符串表示形式插入到此序列中。</li><li>StringBuilder insert(int offset, double d)：将 double 参数的字符串表示形式插入此序列。</li><li>StringBuilder insert(int offset, float f)：将 float 参数的字符串表示形式插入此序列。</li><li>StringBuilder insert(int offset, int i)：将第二个 int 参数的字符串表示形式插入此序列。</li><li>StringBuilder insert(int offset, long l)：将 long 参数的字符串表示形式插入此序列。</li><li>StringBuilder insert(int dstOffset, CharSequence s)：将指定的 CharSequence 插入此序列。</li><li>StringBuilder insert(int dstOffset, CharSequence s, int start, int end)：将指定 CharSequence 的子序列插入此序列。</li><li>StringBuilder insert(int offset, Object obj)：将 Object 参数的字符串表示形式插入此字符序列。</li><li>StringBuilder insert(int offset, String str)：将字符串插入此字符序列</li></ol><h3 id="删除方法" tabindex="-1"><a class="header-anchor" href="#删除方法" aria-hidden="true">#</a> 删除方法</h3><ol><li>StringBuilder delete(int start, int end)：删除此序列的子字符串中的字符。</li><li>StringBuilder deleteCharAt(int index)：删除此序列中指定位置的 char</li></ol><h3 id="查询方法" tabindex="-1"><a class="header-anchor" href="#查询方法" aria-hidden="true">#</a> 查询方法</h3><ol><li>int capacity()：返回当前容量。</li><li>char charAt(int index)：返回此序列中指定索引处的 char 值</li><li>int codePointAt(int index)：返回指定索引处的字符（Unicode 代码点）</li><li>int indexOf(String str)：返回指定子字符串在该字符串中第一次出现的索引。</li><li>int indexOf(String str, int fromIndex)：从指定索引开始，返回第一次出现的指定子字符串在此字符串中的索引</li><li>int lastIndexOf(String str)：返回最后一次出现的指定子字符串在此字符串中的索引。</li><li>int lastIndexOf(String str, int fromIndex)：返回最后一次出现的指定子字符串在此字符串中的索引，从指定索引开始向后搜索。</li><li>int length()：返回长度（字符数）</li></ol><h3 id="修改方法-1" tabindex="-1"><a class="header-anchor" href="#修改方法-1" aria-hidden="true">#</a> 修改方法</h3><ol><li>StringBuilder replace(int start, int end, String str)：用指定的 String 中的字符替换此序列的子字符串中的字符。</li><li>StringBuilder reverse()：导致此字符序列被序列的反向替换</li><li>void setCharAt(int index, char ch)：指定索引处的字符设置为 ch 。</li><li>void setLength(int newLength)：设置字符序列的长度</li><li>String substring(int start)：返回一个新的 String，其中包含当前包含在此字符序列中的字符子序列。</li><li>String substring(int start, int end)：返回一个新的 String，其中包含当前包含在此序列中的字符子序列</li><li>String toString()：返回表示此序列中数据的字符串</li></ol><h2 id="stringbuffer" tabindex="-1"><a class="header-anchor" href="#stringbuffer" aria-hidden="true">#</a> StringBuffer</h2><p>一个线程安全的、可变的字符序列，字符串缓冲区可以安全地供多个线程使用，是线程安全的，常用API同StringBuilder</p>',38),a=[l];function d(h,s){return e(),r("div",null,a)}const g=i(n,[["render",d],["__file","string.html.vue"]]);export{g as default};
